scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_360'] || []

control 'CKV_AWS_360' do
  title 'Ensure DocumentDB has an adequate backup retention period'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_docdb_cluster resources that actually exist, enumerated through
    the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    The default retention of one day means a bad write discovered on Monday
    about a Friday deployment is unrecoverable. Seven days covers a weekend
    plus the time it takes for a data problem to be reported.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_docdb_cluster: backup_retention_period is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_docdb_cluster:

      resource "aws_docdb_cluster" "docs" {
        cluster_identifier      = "docs"
        engine                  = "docdb"
        master_username         = var.master_username
        master_password         = var.master_password
        backup_retention_period = 7
        preferred_backup_window = "03:00-04:00"
      }

    Out of band — aws_docdb_cluster:

      aws docdb modify-db-cluster --db-cluster-identifier docs --backup-retention-period 7 --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_360'
  tag checkov_category:      'BACKUP_AND_RECOVERY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_docdb_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/docdb_cluster#backup-retention-period'
  tag nist:                  ['CP-9', 'SI-12']
  tag nist_r4:               ['CP-9', 'SI-12']
  tag cci:                   ['CCI-000535', 'CCI-001678']
  tag ksi:                   ['KSI-RPL-ABO']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_docdb_cluster', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:backup_retention_period].nil? }

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_docdb_cluster in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_docdb_cluster #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:backup_retention_period] }
      it { should be > 6 }
    end
  end
end
